const nowUtc = new Date();
const pktHour = (nowUtc.getUTCHours() + 5) % 24;
let window = 'post_market';
let windowLabel = 'Post-Market Recap';
let alertWindow = 'POST_MARKET';
if (pktHour >= 7 && pktHour < 11) {
  window = 'pre_market'; windowLabel = 'Pre-Market Outlook'; alertWindow = 'PRE_MARKET';
} else if (pktHour >= 11 && pktHour < 16) {
  window = 'mid_session'; windowLabel = 'Mid-Session Update'; alertWindow = 'MID_SESSION';
}
return [{ json: { window, window_label: windowLabel, alert_window: alertWindow, fired_at: nowUtc.toISOString() } }];

/*
 * Split signals into top pick (highest blended_score) and the rest.
 * Emit ONE item carrying both branches' inputs + the audience + window context.
 * Downstream the workflow forks into 'Top branch' and 'Digest branch'.
 */
const signals = $('Fetch STRONG_BUY signals').all().map(i => i.json);
const users = $('Fetch eligible users').all().map(i => i.json);
const windowCtx = $('Detect window').first().json;

if (signals.length === 0 || users.length === 0) return [];

return [{
  json: {
    top: signals[0],
    rest: signals.slice(1),
    audience: users,
    window: windowCtx.window,
    window_label: windowCtx.window_label,
    alert_window: windowCtx.alert_window,
  },
}];

/* TOP BRANCH — emit 1 item with the top signal + audience + window. */
const src = $input.first().json;
return [{
  json: {
    ...src.top,
    audience: src.audience,
    window: src.window,
    window_label: src.window_label,
    alert_window: src.alert_window,
  },
}];

const src = $('Top: prep').first().json;
let live = {};
let news = [];
try { live = ($('Top: fetch live').all().map(i => i.json))[0] || {}; } catch (e) {}
try { news = $('Top: fetch news').all().map(i => i.json); } catch (e) {}

// Build Gemini request body server-side — embedding JSON.stringify
// inside the HTTP node's jsonBody template double-escapes badly.
const userContent = `Stock: ${src.ticker}\nSignal: STRONG BUY (confidence: ${src.suggestion_confidence})\nHealth label: ${src.health_label}\nDirectional horizon: ${src.horizon}d\nBlended score: ${src.blended_score}\nSignal strength: ${src.signal_strength}\nForecast signed score: ${src.forecast_signed_score}\nReason: ${src.reason}\nDominant news sentiment: ${src.dominant_sentiment}\nContributions: ${JSON.stringify(src.contributions)}\n\nCurrent: close = ${live.close}, change = ${live.change_pct}%, RSI14 = ${live.rsi14}, MA20 = ${live.ma20}, MA50 = ${live.ma50}, MA200 = ${live.ma200}, volatility20d = ${live.volatility20d}, volume_ratio = ${live.volume_ratio}, EPS = ${live.eps}.\n\nTop news headlines:\n- ${(news[0] && news[0].headline) || 'none'}\n- ${(news[1] && news[1].headline) || 'none'}\n\nWrite the explanation now. Start with the recommendation, weave the specific numbers into your reasoning, end with a confident closing statement (NOT a risk warning).`;

const geminiBody = {
  systemInstruction: {
    parts: [{ text: "You are FinMate, a Pakistani stock-market assistant writing for everyday investors who don't know what RSI or MA50 means. Write a confident, friendly 5-7 sentence explanation of why this stock signal was issued. Translate technical terms into meaning, don't define them. Cite specific numbers from the data (price, change %, RSI level, MA crossover position, volume vs 20-day average, EPS if relevant) to back up the recommendation. Mention the news context if relevant. Be direct — DO NOT add disclaimers, risk warnings, hedging language, 'consult an advisor' lines, or 'this is not financial advice' caveats." }],
  },
  contents: [{ role: 'user', parts: [{ text: userContent }] }],
  generationConfig: { maxOutputTokens: 1500, temperature: 0.7, thinkingConfig: { thinkingBudget: 0 } },
};

return [{ json: { ...src, live, news, gemini_body: geminiBody } }];

/*
 * Build detailed HTML + Slack Block Kit payload for the TOP PICK,
 * then fan out to (user × channel) rows. Each row carries the
 * ticker so the next node creates a per-user Alert in DB.
 *
 * Audience is read from Top: prep directly (the canonical source
 * with exactly one entry per user). Re-reading from join context
 * would risk amplification if upstream had multiple runs.
 */
const src = $('Top: prep').first().json;
const joinCtx = $('Top: join context').first().json;
src.live = joinCtx.live || {};
src.news = joinCtx.news || [];
const llmResp = $input.first().json;
const plainEnglish = llmResp?.candidates?.[0]?.content?.parts?.[0]?.text || src.reason;

const ticker = src.ticker;
const windowLabel = src.window_label;
const alertWindow = src.alert_window;
const live = src.live || {};
const news = src.news || [];

const safeNum = (v, d = 2) => (v != null && !isNaN(v) ? Number(v).toFixed(d) : '—');
const pct = live.change_pct != null ? Number(live.change_pct) : 0;
const pctSign = pct >= 0 ? '+' : '';

const newsHtml = news.length
  ? news.map(n => `<li style=\"margin: 4px 0;\"><a href=\"${n.link}\" style=\"color: #2563eb; text-decoration: none;\">${n.headline}</a> <span style=\"color: #6b7280; font-size: 12px;\">· ${n.source} · ${n.sentiment}</span></li>`).join('')
  : '<li style=\"color: #6b7280;\">No recent news</li>';

const html = `
<div style=\"font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; max-width: 560px; margin: 0 auto; padding: 24px; background: #ffffff; border: 1px solid #e5e7eb; border-radius: 12px;\">
  <div style=\"display: flex; justify-content: space-between; align-items: center; border-bottom: 2px solid #f3f4f6; padding-bottom: 12px; margin-bottom: 16px;\">
    <h1 style=\"margin: 0; font-size: 22px; font-weight: 700; color: #1f2937;\">Fin<span style=\"color: #2563eb;\">Mate</span></h1>
    <span style=\"font-size: 12px; color: #6b7280; text-transform: uppercase; letter-spacing: 0.5px;\">Top Pick · ${windowLabel}</span>
  </div>

  <div style=\"background: #ecfdf5; border-left: 4px solid #16a34a; padding: 12px 16px; border-radius: 8px; margin-bottom: 16px; font-size: 14px; color: #14532d;\">
    <strong>Today's top pick</strong> — our highest-confidence STRONG BUY across the market.
  </div>

  <div style=\"background: #f9fafb; border-radius: 10px; padding: 16px; margin-bottom: 16px;\">
    <div style=\"display: flex; justify-content: space-between; align-items: baseline; margin-bottom: 8px;\">
      <h2 style=\"margin: 0; font-size: 28px; font-weight: 700; color: #1f2937;\">${ticker}</h2>
      <span style=\"font-size: 14px; font-weight: 600; color: #16a34a;\">▲ STRONG BUY</span>
    </div>
    <div style=\"font-size: 14px; color: #4b5563;\">
      <strong style=\"color: #1f2937;\">PKR ${safeNum(live.close)}</strong>
      &nbsp;·&nbsp; <span style=\"color: ${pct >= 0 ? '#16a34a' : '#dc2626'};\">${pctSign}${safeNum(pct)}%</span>
      &nbsp;·&nbsp; confidence: <strong>${src.suggestion_confidence}</strong>
    </div>
  </div>

  <p style=\"font-size: 15px; line-height: 1.6; color: #374151; margin: 0 0 16px 0;\">${plainEnglish}</p>

  <table style=\"width: 100%; font-size: 13px; color: #4b5563; border-collapse: collapse; margin-bottom: 16px;\">
    <tr style=\"background: #f9fafb;\">
      <td style=\"padding: 8px 12px; border-radius: 6px 0 0 6px;\">RSI 14</td>
      <td style=\"padding: 8px 12px; text-align: right;\"><strong>${safeNum(live.rsi14, 1)}</strong></td>
      <td style=\"padding: 8px 12px;\">MA 50</td>
      <td style=\"padding: 8px 12px; text-align: right; border-radius: 0 6px 6px 0;\"><strong>${safeNum(live.ma50)}</strong></td>
    </tr>
    <tr>
      <td style=\"padding: 8px 12px;\">MA 200</td>
      <td style=\"padding: 8px 12px; text-align: right;\"><strong>${safeNum(live.ma200)}</strong></td>
      <td style=\"padding: 8px 12px;\">Volatility</td>
      <td style=\"padding: 8px 12px; text-align: right;\"><strong>${safeNum((live.volatility20d || 0) * 100, 1)}%</strong></td>
    </tr>
  </table>

  <h3 style=\"font-size: 13px; text-transform: uppercase; letter-spacing: 0.5px; color: #6b7280; margin: 0 0 8px 0;\">Recent news</h3>
  <ul style=\"list-style: none; padding-left: 0; margin: 0 0 20px 0; font-size: 14px;\">
    ${newsHtml}
  </ul>

  <div style=\"border-top: 1px solid #f3f4f6; padding-top: 12px; font-size: 12px; color: #6b7280; text-align: center;\">
    Don't understand a number? <a href=\"https://finmate.app/docs/notifications\" style=\"color: #2563eb;\">Read the guide →</a><br>
    Sent by FinMate · ${new Date(src.generated_at).toLocaleString('en-PK', { timeZone: 'Asia/Karachi' })} PKT
  </div>
</div>`.trim();

const plain = `Top Pick: ${ticker} — STRONG BUY (${src.suggestion_confidence})\n\n${plainEnglish}\n\nRSI ${safeNum(live.rsi14, 1)} · MA50 ${safeNum(live.ma50)} · MA200 ${safeNum(live.ma200)}\n\nDocs: https://finmate.app/docs/notifications`;

const nowIso = new Date().toISOString();
const newUuid = () => 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c => { const r = Math.random() * 16 | 0; return (c === 'x' ? r : (r & 0x3 | 0x8)).toString(16); });

const alertDetailPayload = {
  ticker, signal: 'STRONG_BUY', confidence: src.suggestion_confidence,
  close: live.close, change_pct: live.change_pct,
  rsi14: live.rsi14, ma50: live.ma50, ma200: live.ma200, volatility20d: live.volatility20d,
  news: (news || []).map(n => ({ headline: n.headline, link: n.link, source: n.source, sentiment: n.sentiment })),
  summary: plainEnglish, window_label: windowLabel, type: 'TOP_PICK',
};

const symbols = [ticker];

const buildIds = (userId) => {
  const alertRowId = newUuid();
  const alertDetailId = newUuid();
  const notificationId = newUuid();
  const alertLogId = newUuid();
  return {
    alert_row_id: alertRowId,
    alert_log_id: alertLogId,
    alert_detail_id: alertDetailId,
    notification_id: notificationId,
    now_iso: nowIso,
    symbols,
    create_alert_body: { id: alertRowId, user_id: userId, ticker, symbols, signal: 'BUY', reason: plainEnglish, alert_window: alertWindow, created_at: nowIso, updated_at: nowIso },
    create_alert_detail_body: { id: alertDetailId, alert_id: alertRowId, payload: alertDetailPayload, created_at: nowIso, updated_at: nowIso },
    create_notification_body: { id: notificationId, user_id: userId, alert_id: alertRowId, type: 'TOP_PICK', category: 'stock', created_at: nowIso, updated_at: nowIso },
  };
};

const rows = [];
const seenUsers = new Set();
for (const u of (src.audience || [])) {
  const user = u.user || {};
  if (!user.id || seenUsers.has(user.id)) continue;
  seenUsers.add(user.id);
  const channels = [];
  if (u.email_enabled && user.email) {
    channels.push({
      channel: 'email', alert_log_id: newUuid(), to: user.email,
      subject: `Top Pick: ${ticker} ▲ STRONG BUY — ${windowLabel}`,
      html, plain,
    });
  }
  if (u.slack_enabled && user.slack_webhook) {
    channels.push({
      channel: 'slack', alert_log_id: newUuid(), to: user.slack_webhook,
      slack_payload: {
        blocks: [
          { type: 'header', text: { type: 'plain_text', text: `Top Pick: ${ticker} ▲ STRONG BUY` } },
          { type: 'section', text: { type: 'mrkdwn', text: `*PKR ${safeNum(live.close)}*  ·  ${pctSign}${safeNum(pct)}%  ·  confidence: *${src.suggestion_confidence}*\n\n${plainEnglish}` } },
          { type: 'context', elements: [{ type: 'mrkdwn', text: `RSI ${safeNum(live.rsi14, 1)} · MA50 ${safeNum(live.ma50)} · MA200 ${safeNum(live.ma200)} · Vol ${safeNum((live.volatility20d || 0) * 100, 1)}%` }] },
          ...(news.length ? [{ type: 'section', text: { type: 'mrkdwn', text: '*Recent news*\n' + news.map(n => `• <${n.link}|${n.headline}> _(${n.source})_`).join('\n') } }] : []),
          { type: 'context', elements: [{ type: 'mrkdwn', text: `<https://finmate.app/docs/notifications|Read the guide →>  ·  FinMate ${windowLabel}` }] },
        ],
      },
    });
  }
  if (channels.length === 0) continue;
  rows.push({
    user_id: user.id, ticker, signal_3class: 'BUY',
    reason: plainEnglish, alert_window: alertWindow,
    channels,
    ...buildIds(user.id),
  });
}
return rows.map(r => ({ json: r }));

/* Carry the just-created alert.id forward alongside the original send payload. */
const sendRow = $('Top: build messages').item.json;
const created = $input.item.json;
const alertId = Array.isArray(created) ? (created[0] && created[0].id) : created.id;
return [{ json: { ...sendRow, alert_id: alertId } }];

/* Restore the row context that was wiped by the two preceding HTTP
 * POSTs (which both ran with Prefer: return=minimal). Downstream
 * channel-switch + send + log nodes all reference $json.X — pull it
 * back from the upstream Code node so those references resolve. */
return [{ json: $('Top: thread alert_id').item.json }];

/* Fan out the per-user row to one item per enabled channel.
 * Each channel sub-row carries its own alert_log_id; the alert + alert_detail + notification rows were already created once per user. */
const rows = $input.all().map(i => i.json);
const out = [];
for (const row of rows) {
  for (const ch of (row.channels || [])) {
    out.push({ json: { ...row, ...ch } });
  }
}
return out;

/* DIGEST BRANCH — emit 1 item with rest signals + ticker list + audience. */
const src = $('Split top + rest').first().json;
if (!src || !src.rest || src.rest.length === 0) return [];
return [{
  json: {
    rest: src.rest,
    tickers: src.rest.map(s => s.ticker).join(','),
    audience: src.audience,
    window: src.window,
    window_label: src.window_label,
    alert_window: src.alert_window,
  },
}];

const src = $('Digest: prep rest').first().json;
let lives = [];
try { lives = $('Digest: fetch live (batch)').all().map(i => i.json); } catch (e) {}
const liveByTicker = {};
for (const l of lives) liveByTicker[l.ticker] = l;
const enriched = src.rest.map(s => ({ ...s, live: liveByTicker[s.ticker] || {} }));

// Build the Gemini request body server-side so the HTTP node can
// pass it as one clean JSON.stringify() call — avoids the
// double-escape problem of embedding JSON.stringify INSIDE another
// JSON string literal.
const userContent = enriched.map(s => {
  const live = s.live || {};
  return `${s.ticker}: rsi=${live.rsi14 ?? 'n/a'}, ma50=${live.ma50 ?? 'n/a'}, ma200=${live.ma200 ?? 'n/a'}, close=${live.close ?? 'n/a'}, change_pct=${live.change_pct ?? 'n/a'}, health=${s.health_label ?? 'n/a'}`;
}).join('\n');

const geminiBody = {
  systemInstruction: {
    parts: [{ text: 'You are FinMate. For each STRONG_BUY stock below, write a short ONE-SENTENCE plain-English summary in 12 words or fewer — translate the numbers into meaning, no jargon. Return ONLY a single JSON object mapping ticker to summary string, no markdown, no surrounding text. Example: {"HBL":"Banking momentum continuing with strong volume.","OGDC":"Energy sector picking up after recent dip."}' }],
  },
  contents: [{ role: 'user', parts: [{ text: userContent }] }],
  generationConfig: { maxOutputTokens: 2000, temperature: 0.4, responseMimeType: 'application/json', thinkingConfig: { thinkingBudget: 0 } },
};

return [{ json: { ...src, enriched, gemini_body: geminiBody } }];

/* Build digest message (table format) — one row per (user × channel).
 * Each row contains the FULL list of remaining STRONG_BUYs as a compact
 * table. Logged once per send with ticker='DIGEST'.
 *
 * Audience comes from Digest: prep rest (canonical one-entry-per-user
 * source) — re-reading via join context risks amplification if
 * upstream branching produced multiple runs. */
const src = $('Digest: prep rest').first().json;
const joinCtx = $('Digest: join context').first().json;
src.enriched = joinCtx.enriched || src.rest || [];
const llmResp = $input.first().json;
let summaries = {};
try {
  const txt = llmResp?.candidates?.[0]?.content?.parts?.[0]?.text || '{}';
  summaries = JSON.parse(txt);
} catch (e) {
  summaries = {};
}

const safeNum = (v, d = 2) => (v != null && !isNaN(v) ? Number(v).toFixed(d) : '—');
const stocks = src.enriched;
const windowLabel = src.window_label;
const alertWindow = src.alert_window;

const tableRowsHtml = stocks.map(s => {
  const live = s.live || {};
  const pct = live.change_pct != null ? Number(live.change_pct) : 0;
  const pctSign = pct >= 0 ? '+' : '';
  const pctColor = pct >= 0 ? '#16a34a' : '#dc2626';
  return `
    <tr style=\"border-bottom: 1px solid #f3f4f6;\">
      <td style=\"padding: 10px 8px; font-weight: 600; color: #1f2937;\">${s.ticker}</td>
      <td style=\"padding: 10px 8px; text-align: right; color: #1f2937;\">${safeNum(live.close)}</td>
      <td style=\"padding: 10px 8px; text-align: right; color: ${pctColor};\">${pctSign}${safeNum(pct)}%</td>
      <td style=\"padding: 10px 8px; text-align: right; color: #4b5563;\">${safeNum(live.rsi14, 1)}</td>
      <td style=\"padding: 10px 8px; color: #4b5563; font-size: 12px;\">${summaries[s.ticker] || s.reason || ''}</td>
    </tr>`;
}).join('');

const slackRows = stocks.map(s => {
  const live = s.live || {};
  const pct = live.change_pct != null ? Number(live.change_pct) : 0;
  const pctSign = pct >= 0 ? '+' : '';
  return `*${s.ticker}*  ·  PKR ${safeNum(live.close)}  ·  ${pctSign}${safeNum(pct)}%  ·  RSI ${safeNum(live.rsi14, 1)}\n_${summaries[s.ticker] || s.reason || ''}_`;
}).join('\n\n');

const html = `
<div style=\"font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; max-width: 640px; margin: 0 auto; padding: 24px; background: #ffffff; border: 1px solid #e5e7eb; border-radius: 12px;\">
  <div style=\"display: flex; justify-content: space-between; align-items: center; border-bottom: 2px solid #f3f4f6; padding-bottom: 12px; margin-bottom: 16px;\">
    <h1 style=\"margin: 0; font-size: 22px; font-weight: 700; color: #1f2937;\">Fin<span style=\"color: #2563eb;\">Mate</span></h1>
    <span style=\"font-size: 12px; color: #6b7280; text-transform: uppercase; letter-spacing: 0.5px;\">Other Top Performers · ${windowLabel}</span>
  </div>
  <p style=\"font-size: 14px; color: #4b5563; margin: 0 0 16px 0;\">${stocks.length} more strong-buy moves on PSX today:</p>
  <table style=\"width: 100%; font-size: 13px; border-collapse: collapse;\">
    <thead>
      <tr style=\"background: #f9fafb; text-transform: uppercase; font-size: 11px; color: #6b7280; letter-spacing: 0.5px;\">
        <th style=\"padding: 8px; text-align: left;\">Ticker</th>
        <th style=\"padding: 8px; text-align: right;\">Price</th>
        <th style=\"padding: 8px; text-align: right;\">Change</th>
        <th style=\"padding: 8px; text-align: right;\">RSI</th>
        <th style=\"padding: 8px; text-align: left;\">Note</th>
      </tr>
    </thead>
    <tbody>${tableRowsHtml}</tbody>
  </table>
  <div style=\"border-top: 1px solid #f3f4f6; padding-top: 12px; margin-top: 20px; font-size: 12px; color: #6b7280; text-align: center;\">
    Don't understand a number? <a href=\"https://finmate.app/docs/notifications\" style=\"color: #2563eb;\">Read the guide →</a><br>
    Sent by FinMate · ${windowLabel}
  </div>
</div>`.trim();

const plain = `Other top performers (${stocks.length})\n\n` + stocks.map(s => {
  const live = s.live || {};
  const pct = live.change_pct != null ? Number(live.change_pct) : 0;
  const pctSign = pct >= 0 ? '+' : '';
  return `${s.ticker}  PKR ${safeNum(live.close)}  ${pctSign}${safeNum(pct)}%  RSI ${safeNum(live.rsi14, 1)}\n${summaries[s.ticker] || s.reason || ''}`;
}).join('\n\n') + `\n\nDocs: https://finmate.app/docs/notifications`;

const nowIso = new Date().toISOString();
const newUuid = () => 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c => { const r = Math.random() * 16 | 0; return (c === 'x' ? r : (r & 0x3 | 0x8)).toString(16); });

const alertDetailPayload = {
  tickers: stocks.map(s => ({
    ticker: s.ticker,
    close: s.live && s.live.close,
    change_pct: s.live && s.live.change_pct,
    rsi14: s.live && s.live.rsi14,
    summary: summaries[s.ticker] || s.reason || '',
  })),
  count: stocks.length,
  window_label: windowLabel,
  type: 'DIGEST',
};

const symbols = stocks.map(s => s.ticker);
const digestReason = `Digest of ${stocks.length} STRONG_BUY signals: ${symbols.join(', ')}`;

const buildIds = (userId) => {
  const alertRowId = newUuid();
  const alertDetailId = newUuid();
  const notificationId = newUuid();
  const alertLogId = newUuid();
  return {
    alert_row_id: alertRowId,
    alert_log_id: alertLogId,
    alert_detail_id: alertDetailId,
    notification_id: notificationId,
    now_iso: nowIso,
    symbols,
    create_alert_body: { id: alertRowId, user_id: userId, ticker: 'DIGEST', symbols, signal: 'BUY', reason: digestReason, alert_window: alertWindow, created_at: nowIso, updated_at: nowIso },
    create_alert_detail_body: { id: alertDetailId, alert_id: alertRowId, payload: alertDetailPayload, created_at: nowIso, updated_at: nowIso },
    create_notification_body: { id: notificationId, user_id: userId, alert_id: alertRowId, type: 'DIGEST', category: 'digest', created_at: nowIso, updated_at: nowIso },
  };
};

const rows = [];
const seenUsers = new Set();
for (const u of (src.audience || [])) {
  const user = u.user || {};
  if (!user.id || seenUsers.has(user.id)) continue;
  seenUsers.add(user.id);
  const channels = [];
  if (u.email_enabled && user.email) {
    channels.push({
      channel: 'email', alert_log_id: newUuid(), to: user.email,
      subject: `${stocks.length} more strong-buy moves — ${windowLabel}`,
      html, plain,
    });
  }
  if (u.slack_enabled && user.slack_webhook) {
    channels.push({
      channel: 'slack', alert_log_id: newUuid(), to: user.slack_webhook,
      slack_payload: {
        blocks: [
          { type: 'header', text: { type: 'plain_text', text: `Other top performers — ${windowLabel}` } },
          { type: 'section', text: { type: 'mrkdwn', text: `${stocks.length} more strong-buy moves on PSX today:\n\n${slackRows}` } },
          { type: 'context', elements: [{ type: 'mrkdwn', text: `<https://finmate.app/docs/notifications|Read the guide →>  ·  FinMate ${windowLabel}` }] },
        ],
      },
    });
  }
  if (channels.length === 0) continue;
  rows.push({
    user_id: user.id, ticker: 'DIGEST', signal_3class: 'BUY',
    reason: digestReason, alert_window: alertWindow,
    channels,
    ...buildIds(user.id),
  });
}
return rows.map(r => ({ json: r }));

const sendRow = $('Digest: build messages').item.json;
const created = $input.item.json;
const alertId = Array.isArray(created) ? (created[0] && created[0].id) : created.id;
return [{ json: { ...sendRow, alert_id: alertId } }];

const rows = $input.all().map(i => i.json);
const out = [];
for (const row of rows) {
  for (const ch of (row.channels || [])) {
